package br.com.petshop.controller;

import br.com.petshop.entity.*; import br.com.petshop.repository.*; import br.com.petshop.service.CrudServices; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.time.*; import java.util.List;

@RestController @RequestMapping("/api/tutores") class TutorController {private final TutorRepository r;TutorController(TutorRepository r){this.r=r;}@GetMapping List<Tutor> all(@RequestParam(defaultValue="")String busca){return busca.isBlank()?r.findAll():r.findByNomeContainingIgnoreCase(busca);}@PostMapping Tutor save(@Valid @RequestBody Req x){return r.save(new Tutor(x.nome(),x.telefone(),x.email(),x.cpf(),x.endereco()));}@DeleteMapping("/{id}")void del(@PathVariable Long id){r.deleteById(id);}record Req(@NotBlank String nome,@NotBlank String telefone,@Email String email,@NotBlank String cpf,String endereco){}}

@RestController @RequestMapping("/api/pets") class PetController {private final PetRepository r;private final CrudServices s;PetController(PetRepository r,CrudServices s){this.r=r;this.s=s;}@GetMapping List<Pet> all(){return r.findAll();}@PostMapping Pet save(@Valid @RequestBody Req x){return r.save(new Pet(x.nome(),x.especie(),x.raca(),x.idade(),s.tutor(x.tutorId())));}@DeleteMapping("/{id}")void del(@PathVariable Long id){r.deleteById(id);}record Req(@NotBlank String nome,String especie,String raca,@Min(0)Integer idade,@NotNull Long tutorId){}}

@RestController @RequestMapping("/api/produtos") class ProdutoController {private final ProdutoRepository r;ProdutoController(ProdutoRepository r){this.r=r;}@GetMapping List<Produto> all(){return r.findAll();}@PostMapping Produto save(@Valid @RequestBody Req x){return r.save(new Produto(x.nome(),x.preco(),x.estoque()));}@DeleteMapping("/{id}")void del(@PathVariable Long id){r.deleteById(id);}record Req(@NotBlank String nome,@NotNull @DecimalMin("0.0") BigDecimal preco,@NotNull @Min(0) Integer estoque){}}

@RestController @RequestMapping("/api/agendamentos") class AgendamentoController {private final AgendamentoRepository r;private final CrudServices s;AgendamentoController(AgendamentoRepository r,CrudServices s){this.r=r;this.s=s;}@GetMapping List<Agendamento> all(@RequestParam(required=false)LocalDate data){return data==null?r.findAll():r.findByData(data);}@PostMapping Agendamento save(@Valid @RequestBody Req x){return s.salvarAgendamento(x.data(),x.horario(),x.servico(),x.status(),x.petId(),null);}@DeleteMapping("/{id}")void del(@PathVariable Long id){r.deleteById(id);}record Req(@NotNull LocalDate data,@NotNull LocalTime horario,@NotNull Agendamento.Servico servico,@NotNull Agendamento.Status status,@NotNull Long petId){}}

@RestController @RequestMapping("/api/dashboard") class DashboardController {private final TutorRepository t;private final AgendamentoRepository a;DashboardController(TutorRepository t,AgendamentoRepository a){this.t=t;this.a=a;}@GetMapping Summary summary(){LocalDate d=LocalDate.now();return new Summary(t.count(),a.countByData(d),d);}record Summary(long totalTutores,long agendamentosHoje,LocalDate data){}}
